#!/bin/bash
# native-sim-template-version: 1
set -euo pipefail

if [ -n "${NATIVE_SIM_DEV_CONFIG:-}" ] && [ -f "$NATIVE_SIM_DEV_CONFIG" ]; then
  # Generated by the workflow with shell-escaped values.
  # shellcheck source=/dev/null
  source "$NATIVE_SIM_DEV_CONFIG"
fi
cd "${NATIVE_SIM_PROJECT_DIR:?Run this inside a native-sim SSH session or export workflow}"
: "${NATIVE_SIM_IPA_FILE:?Missing IPA output path}"

CONTAINER=""
for NATIVE_DIR in ios .; do
  [ -d "$NATIVE_DIR" ] || continue
  CANDIDATES=()
  for WORKSPACE in "$NATIVE_DIR"/*.xcworkspace; do
    if [ -f "$WORKSPACE/contents.xcworkspacedata" ]; then
      CANDIDATES+=("$WORKSPACE")
    fi
  done
  if [ "${#CANDIDATES[@]}" -eq 0 ]; then
    for PROJECT in "$NATIVE_DIR"/*.xcodeproj; do
      if [ -f "$PROJECT/project.pbxproj" ]; then
        CANDIDATES+=("$PROJECT")
      fi
    done
  fi
  if [ "${#CANDIDATES[@]}" -gt 1 ]; then
    echo "Multiple Xcode projects or workspaces in $NATIVE_DIR; select one app directory." >&2
    exit 1
  fi
  if [ "${#CANDIDATES[@]}" -eq 1 ]; then
    CONTAINER="${CANDIDATES[0]}"
    break
  fi
done
[ -n "$CONTAINER" ] || { echo "No Xcode project or workspace found." >&2; exit 1; }
case "$CONTAINER" in
  *.xcworkspace) XCODE_ARGS=(-workspace "$CONTAINER"); DEFAULT_SCHEME=$(basename "$CONTAINER" .xcworkspace) ;;
  *.xcodeproj) XCODE_ARGS=(-project "$CONTAINER"); DEFAULT_SCHEME=$(basename "$CONTAINER" .xcodeproj) ;;
esac
SCHEME="${NATIVE_SIM_SCHEME:-$DEFAULT_SCHEME}"

# Device builds are separate from the simulator's Debug/Release products.
# An unsigned IPA needs no signing certificate or provisioning profile here.
echo "Building an unsigned Release IPA for $SCHEME..."
xcodebuild "${XCODE_ARGS[@]}" \
  -scheme "$SCHEME" \
  -configuration Release \
  -sdk iphoneos \
  -destination 'generic/platform=iOS' \
  -derivedDataPath build/native-sim-device \
  ARCHS=arm64 \
  CODE_SIGNING_ALLOWED=NO \
  CODE_SIGNING_REQUIRED=NO \
  CODE_SIGN_IDENTITY= \
  build

APP=$(find build/native-sim-device/Build/Products/Release-iphoneos -maxdepth 1 -type d -name '*.app' | head -1)
[ -n "$APP" ] || { echo "No device .app produced." >&2; exit 1; }
PLATFORM=$(/usr/libexec/PlistBuddy -c 'Print CFBundleSupportedPlatforms:0' "$APP/Info.plist")
if [ "$PLATFORM" != iPhoneOS ]; then
  echo "Refusing to package a non-device app as an IPA." >&2
  exit 1
fi

OUTPUT_DIR=$(dirname "$NATIVE_SIM_IPA_FILE")
mkdir -p "$OUTPUT_DIR"
STAGING=$(mktemp -d "$OUTPUT_DIR/.native-sim-ipa.XXXXXX")
trap 'rm -rf "$STAGING"' EXIT
mkdir "$STAGING/Payload"
cp -R "$APP" "$STAGING/Payload/"
APP_COPY="$STAGING/Payload/$(basename "$APP")"
rm -rf "$APP_COPY/_CodeSignature"
rm -f "$APP_COPY/embedded.mobileprovision"
ditto -c -k --keepParent "$STAGING/Payload" "$STAGING/unsigned.ipa"

# Publish only a complete ZIP. Existing downloads keep their original file open.
mv -f "$STAGING/unsigned.ipa" "$NATIVE_SIM_IPA_FILE"
echo "Unsigned IPA ready: $NATIVE_SIM_IPA_FILE"
if [ -n "${NATIVE_SIM_PREVIEW_URL:-}" ]; then
  echo "Open this in the same browser used for your authenticated preview:"
  echo "${NATIVE_SIM_PREVIEW_URL%/}/__native-sim/unsigned.ipa"
fi
